#include <iostream>
#include <string>
using namespace std;

int main() {
    string s = "Goa is sunny";
    s.replace(7, 5, "warm");
    cout << s << endl;
    s.erase(3, 3);
    cout << s << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string text = "42";
    int n = stoi(text);
    cout << n + 1 << endl;
    string label = "Total: " + to_string(n * 2);
    cout << label << endl;
    return 0;
}

