bug.fixed:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string text = "abc";
    try {
        int n = stoi(text);
        cout << n << endl;
    } catch (const exception&) {
        cout << "Not a number" << endl;
    }
    return 0;
}

